//
// tb_mul8s - Self-checking testbench for any mul8s_* variant.
//
// Compile-time options:
//   +define+DUT=<module>   design under test (default: mul8s_bw)
//   +define+EXACT_ORACLE   additionally compare against the SystemVerilog
//                          '*' operator (only valid for exact variants)
// Run-time options:
//   +VECTORS=<file>        expected results generated by models/gen_vectors.py
//                          (line k = expected p for index k = {a[7:0], b[7:0]})
//
// Phase 1 runs named directed corner cases, phase 2 sweeps all 65,536 pairs.
// The test ends with $fatal (non-zero exit status) on any mismatch.
// The time unit is set by the simulator command line (RTL carries no `timescale).

`ifndef DUT
`define DUT mul8s_bw
`endif

`define STRINGIFY(x) `"x`"

module tb_mul8s;

  localparam int NUM_PAIRS    = 1 << 16;
  localparam int MAX_REPORTED = 16;  // mismatches printed in full
  localparam int INT8_MIN     = -128;
  localparam int INT8_MAX     = 127;

  logic signed [7:0]  a;
  logic signed [7:0]  b;
  logic signed [15:0] p;

  logic        [15:0] expected_mem[NUM_PAIRS];
  int                 n_checked;
  int                 n_failed;

  `DUT u_dut (
      .a(a),
      .b(b),
      .p(p)
  );

  task automatic check_pair(input int op_a, input int op_b, input string tag);
    logic [15:0]        index;
    logic signed [15:0] expected;
    logic               failed;

    if (op_a < INT8_MIN || op_a > INT8_MAX || op_b < INT8_MIN || op_b > INT8_MAX)
      $fatal(1, "TB error: operand out of INT8 range in case '%s' (a=%0d, b=%0d)", tag, op_a, op_b);

    a = op_a[7:0];
    b = op_b[7:0];
    #1;

    index    = {a, b};
    expected = expected_mem[index];
    failed   = (p !== expected);
`ifdef EXACT_ORACLE
    begin
      logic signed [15:0] sv_product;
      sv_product = a * b;
      if (sv_product !== expected)
        $fatal(1, "TB error: vector file disagrees with SV '*' at a=%0d b=%0d", a, b);
    end
`endif

    n_checked++;
    if (failed) begin
      n_failed++;
      if (n_failed <= MAX_REPORTED)
        $display("MISMATCH [%s] a=%0d (0x%02h) b=%0d (0x%02h) expected=%0d (0x%04h) got=%0d (0x%04h) diff=0x%04h",
                 tag, a, a, b, b, expected, expected, p, p, p ^ expected);
    end
  endtask

  initial begin
    string vectors;
    int    fd;
    int    n_directed;

    if (!$value$plusargs("VECTORS=%s", vectors)) $fatal(1, "TB error: +VECTORS=<file> is required");
    fd = $fopen(vectors, "r");
    if (fd == 0) $fatal(1, "TB error: cannot open vector file '%s'", vectors);
    $fclose(fd);
    $readmemh(vectors, expected_mem);

    $display("tb_mul8s: DUT=%s vectors=%s", `STRINGIFY(`DUT), vectors);
`ifdef EXACT_ORACLE
    $display("tb_mul8s: SV '*' cross-check enabled");
`endif

    // ---------------------------------------------------------------------
    // Phase 1: directed signed-arithmetic corner cases
    // ---------------------------------------------------------------------
    check_pair(-128, -128, "min x min (largest product, 0x4000)");
    check_pair(-128, 127, "min x max");
    check_pair(127, -128, "max x min");
    check_pair(127, 127, "max x max");
    check_pair(-1, -1, "-1 x -1");
    check_pair(-1, -128, "-1 x min");
    check_pair(-128, -1, "min x -1");
    check_pair(-1, 127, "-1 x max");
    check_pair(1, -128, "1 x min");
    check_pair(-128, 0, "min x 0");
    check_pair(0, -128, "0 x min");
    check_pair(0, 0, "0 x 0");
    check_pair(1, 1, "1 x 1");
    check_pair(85, -86, "0x55 x 0xAA (alternating bits, mixed sign)");
    check_pair(-86, 85, "0xAA x 0x55 (alternating bits, mixed sign)");
    check_pair(-86, -86, "0xAA x 0xAA (alternating bits, both negative)");
    check_pair(64, -2, "power of two x negative");
    n_directed = n_checked;
    $display("tb_mul8s: directed  %0d/%0d passed", n_directed - n_failed, n_directed);

    // ---------------------------------------------------------------------
    // Phase 2: exhaustive sweep of the full input space
    // ---------------------------------------------------------------------
    for (int ia = INT8_MIN; ia <= INT8_MAX; ia++) begin
      for (int ib = INT8_MIN; ib <= INT8_MAX; ib++) begin
        check_pair(ia, ib, "exhaustive");
      end
    end

    if (n_checked - n_directed != NUM_PAIRS)
      $fatal(1, "TB error: exhaustive phase checked %0d pairs, expected %0d", n_checked - n_directed, NUM_PAIRS);

    if (n_failed == 0) begin
      $display("tb_mul8s: exhaustive %0d/%0d passed", NUM_PAIRS, NUM_PAIRS);
      $display("PASS: %s", `STRINGIFY(`DUT));
      $finish;
    end else begin
      $fatal(1, "FAIL: %s, %0d of %0d checks mismatched", `STRINGIFY(`DUT), n_failed, n_checked);
    end
  end

endmodule
